{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Whole-body autoradiography in mice after i.v. administration of a closely related aminoglycoside-like glycoside showed rapid distribution to all tissues except brain and nervous tissues, directly demonstrating negligible CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "In monkeys, the glycosylated polyketide mithramycin reached a peak CSF:plasma ratio of only 0.12 and little material was found in normal brains, indicating poor CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "In humans, the macrolide glycoside erythromycin achieved only 0.1-2.5 µg/mL CSF versus 8-12 µg/mL serum even in meningitis, showing inadequate CNS access for a large glycoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Digitoxin, a bulky cardiac glycoside, showed a very low CSF/plasma ratio of 0.01-0.03 in dogs, providing direct evidence that large multi-ring glycosides do not readily cross the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Systemic gentamicin administration in humans does not produce adequate therapeutic CSF levels, supporting poor CNS exposure for polar, ionizable glycoside/aminoglycoside-like structures.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a high-molecular-weight, polar, ionizable anthracycline glycoside. Direct CNS-exposure evidence from closely transferable glycoside, aminoglycoside, and macrolide analogues uniformly shows negligible brain or CSF penetration, with no contradictory evidence. Therefore, meaningful CNS access after systemic administration is predicted to fail.",
  "evidence_gaps": [
    "No direct brain or CSF pharmacokinetic data are available for the query molecule itself.",
    "Potential carrier-mediated uptake or active transport into the CNS was not directly assessed.",
    "Human data for the exact query structure are absent; conclusions rely on transferable analogue evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

